#!/usr/bin/env node
/**
 * Inline components.css + pages.css into one file so Turbopack cannot emit
 * two render-blocking CSS chunks from site.css @import.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const stylesDir = path.join(path.dirname(fileURLToPath(import.meta.url)), "../src/styles");
const components = fs.readFileSync(path.join(stylesDir, "components.css"), "utf8");
const pages = fs.readFileSync(path.join(stylesDir, "pages.css"), "utf8");
const banner =
  "/* Generated by scripts/bundle-site-css.mjs — do not edit. Source: components.css + pages.css */\n";

fs.writeFileSync(path.join(stylesDir, "site.bundle.css"), `${banner}\n${components}\n${pages}\n`);
